import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const newTable = () => ({ kind: 'table', map: new Map(), defined: false })
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Parser {
  constructor(line) { this.s = line; this.i = 0 }
  ws() { while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++ }
  // peek after whitespace; null at end of line or comment
  peek() {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';') return null
    return c
  }
  basicString() {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      const c = s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.i++; return out }
      if (c === '\\') {
        const e = s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; this.i += 2; continue }
        if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 6; continue
        }
        fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(this.i + 1)))
      }
      out += c; this.i++
    }
  }
  literalString() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return r
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      this.ws()
      if (this.s[this.i] !== '.') return names
      this.i++
      this.ws()
      names.push(this.name())
    }
  }
  value(path) {
    const c = this.peek()
    if (c === null || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { kind: 'string', v: this.basicString() }
    if (c === "'") return { kind: 'string', v: this.literalString() }
    if (c === '[') {
      this.i++
      const items = []
      for (;;) {
        if (this.peek() === ']') { this.i++; break }
        items.push(this.value(path.concat([`[${items.length}]`])))
        const d = this.peek()
        if (d === ',') { this.i++; continue }
        if (d === ']') { this.i++; break }
        fail('unterminated array')
      }
      return { kind: 'array', items, aot: false }
    }
    if (c === '{') {
      this.i++
      const t = newTable()
      if (this.peek() === '}') { this.i++; return t }
      for (;;) {
        this.peek()
        const names = this.dotted()
        if (this.peek() !== '=') fail('expected = in an inline table')
        this.i++
        const v = this.value(path.concat(names))
        assign(t, path, names, v)
        const d = this.peek()
        if (d === ',') { this.i++; continue }
        if (d === '}') { this.i++; return t }
        fail('unterminated inline table')
      }
    }
    const st = this.i
    while (this.i < this.s.length && !' \t,]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { kind: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { kind: 'integer', v: Number(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { kind: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
}

const pathStr = (a) => a.join('.').replace(/\.\[/g, '[')

// walk names (all but last) from table t, creating tables; returns the table
function walk(t, base, names) {
  let cur = t
  for (let k = 0; k < names.length; k++) {
    const n = names[k]
    let nx = cur.map.get(n)
    if (nx === undefined) { nx = newTable(); cur.map.set(n, nx) }
    if (nx.kind === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
    if (nx.kind !== 'table') fail(`${pathStr(base.concat(names.slice(0, k + 1)))} is not a table`)
    cur = nx
  }
  return cur
}

function assign(t, base, names, v) {
  const parent = walk(t, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (parent.map.has(last)) fail(`key ${pathStr(base.concat(names))} is defined twice`)
  parent.map.set(last, v)
}

function parse(text) {
  const root = newTable()
