  lines.forEach((line, idx) => {
    try {
      const p = new Parser(line)
      p.ws()
      const c = line[p.i]
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') {
        const aot = line[p.i + 1] === '['
        p.i += aot ? 2 : 1
        p.ws()
        const names = p.dotted()
        p.ws()
        for (let k = 0; k < (aot ? 2 : 1); k++) {
          if (line[p.i] !== ']') fail('unterminated table header')
          p.i++
        }
        if (p.peek() !== null) fail('trailing text after a table header')
        const parent = walk(root, [], names.slice(0, -1))
        const base = names.slice(0, -1)
        const last = names[names.length - 1]
        const ex = parent.map.get(last)
        if (aot) {
          let el
          if (ex === undefined) {
            el = newTable(); el.defined = true
            parent.map.set(last, { kind: 'array', items: [el], aot: true })
          } else if (ex.kind === 'array' && ex.aot) {
            el = newTable(); el.defined = true; ex.items.push(el)
          } else fail(`${pathStr(names)} is not an array of tables`)
          cur = el
        } else {
          if (ex === undefined) {
            const t = newTable(); t.defined = true
            parent.map.set(last, t); cur = t
          } else if (ex.kind !== 'table') fail(`${pathStr(names)} is not a table`)
          else {
            if (ex.defined) fail(`table ${pathStr(names)} is defined twice`)
            ex.defined = true; cur = ex
          }
        }
        void base
        curPath = names
        return
      }
      const names = p.dotted()
      if (p.peek() !== '=') fail('expected key = value')
      p.i++
      const v = p.value(curPath.concat(names))
      if (p.peek() !== null) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof Fail) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (ch) => ch.codePointAt(0))
  const y = Array.from(b, (ch) => ch.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.kind === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.kind === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v) ?? 'null'
}

function keysOut(n, path, out) {
  if (n.kind === 'table') {
    for (const k of sortedKeys(n)) {
      const p = path === null ? k : path + '.' + k
      out.push(`${p} ${n.map.get(k).kind}`)
      keysOut(n.map.get(k), p, out)
    }
  } else if (n.kind === 'array') {
    n.items.forEach((x, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${x.kind}`)
      keysOut(x, p, out)
    })
  }
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'json' && mode[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const root = parse(readFileSync(0, 'utf8'))
  if (mode[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keysOut(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
